insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-ai-seed', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"","attribution_required":false,"attribution_text":"","import_policy":"not_applicable","update_history":[],"id":"src-ai-seed","source_name":"Nội dung mẫu do AI (Claude) soạn cho Nihongo Compass — chưa xác minh","source_url":"","source_type":"self_authored","publisher":"Nihongo Compass (soạn bởi AI theo yêu cầu của chủ dự án)","purpose":"Dữ liệu mẫu để ứng dụng chạy được ngay. Cần giáo viên/người bản ngữ rà soát trước khi coi là đáng tin.","level_scope":"N5–N1 (cấp độ chỉ là gợi ý)","license_note":"Văn bản do AI viết mới, không sao chép từ sách/đề thi. Chủ dự án quyết định giấy phép khi công bố. Chưa qua rà soát của người bản ngữ nên có thể còn sai sót.","verification_status":"ai_generated","reviewed_by":null,"last_verified":null,"reuse_allowed":"own","notes":"Mọi bản ghi seed trỏ về nguồn này cho tới khi được rà soát và gán nguồn tham khảo cụ thể.","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-jlpt-official', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"Không nhập tự động. Trang JLPT không công bố danh sách từ vựng/Kanji/ngữ pháp dạng dữ liệu; câu hỏi mẫu chứa tác phẩm bên thứ ba cần xin phép riêng.","attribution_required":false,"attribution_text":"","import_policy":"blocked","update_history":[],"id":"src-jlpt-official","source_name":"JLPT — Trang chính thức (Japanese-Language Proficiency Test)","source_url":"https://www.jlpt.jp/e/","source_type":"official_exam","publisher":"The Japan Foundation & Japan Educational Exchanges and Services (JEES)","purpose":"Thông tin kỳ thi, đăng ký, câu hỏi mẫu, tài liệu ôn thi chính thức.","level_scope":"N1–N5","license_note":"Theo Site Policy (https://jlpt.jp/e/policy.html): nội dung có bản quyền; dùng cho học tập cá nhân được phép; trích dẫn hợp lý có ghi nguồn; dùng cho giáo dục tiếng Nhật không thu phí có điều kiện ghi nguồn. Câu hỏi mẫu chứa tác phẩm của bên thứ ba và cần xin phép riêng. Không được nhúng (framing) trang. → App chỉ liên kết tới trang này, KHÔNG sao chép câu hỏi mẫu.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-22","reuse_allowed":"conditional","notes":"URL, đơn vị xuất bản và điều khoản đã được đọc tự động ngày 2026-10-22; cần người chịu trách nhiệm dự án xác nhận trước khi dùng thương mại.","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-jlpt-guideline', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"Không nhập tự động. Chỉ dùng số liệu cấu trúc kỳ thi (đã nhập thủ công vào cấu hình); không có dữ liệu để nhập tự động.","attribution_required":false,"attribution_text":"","import_policy":"blocked","update_history":[],"id":"src-jlpt-guideline","source_name":"JLPT — Thời gian thi, phần chấm điểm, điểm đỗ, mô tả năng lực theo cấp","source_url":"https://www.jlpt.jp/e/guideline/testsections.html","source_type":"official_exam","publisher":"The Japan Foundation & JEES","purpose":"Cấu hình bài thi trong app (thời gian từng phần, phần chấm điểm, điểm đỗ) lấy từ đây. Xem thêm: /e/guideline/results.html và /e/about/levelsummary.html.","level_scope":"N1–N5","license_note":"Chỉ dùng SỐ LIỆU THỰC TẾ (thời gian, thang điểm, điểm đỗ) để mô tả cấu trúc kỳ thi, kèm ghi nguồn; không sao chép văn bản gốc. Trang ghi chú rằng thời gian có thể thay đổi.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-22","reuse_allowed":"conditional","notes":"Số liệu trong src/config/jlpt.ts đối chiếu ngày 2026-10-22: N1 110+55 phút; N2 105+50; N3 30+70+40; N4 25+55+35; N5 20+40+30. Điểm đỗ tổng: N1 100, N2 90, N3 95, N4 90, N5 80; điểm liệt từng phần 19 (N4/N5: 38 cho Kiến thức ngôn ngữ・Đọc hiểu).","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-jlpt-faq', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"Không nhập tự động. Chỉ trích dẫn ý; không có dữ liệu để nhập tự động.","attribution_required":false,"attribution_text":"","import_policy":"blocked","update_history":[],"id":"src-jlpt-faq","source_name":"JLPT FAQ — về việc không còn công bố danh sách từ vựng/Kanji/ngữ pháp theo cấp","source_url":"https://www.jlpt.jp/e/faq/index.html","source_type":"official_exam","publisher":"The Japan Foundation & JEES","purpose":"Căn cứ để app ghi rõ: cấp độ N5–N1 của từ/Kanji trong app chỉ là GỢI Ý.","level_scope":"N1–N5","license_note":"Chỉ trích dẫn ý (JLPT thấy việc công bố danh sách từ vựng, Kanji, ngữ pháp 'không nhất thiết phù hợp' sau lần sửa đổi 2010). Không sao chép văn bản.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-22","reuse_allowed":"conditional","notes":"","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-jpf', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"Không nhập tự động. Chưa xác nhận được quyền sử dụng lại.","attribution_required":false,"attribution_text":"","import_policy":"blocked","update_history":[],"id":"src-jpf","source_name":"Japan Foundation (Quỹ Giao lưu Quốc tế Nhật Bản) — Trang chủ","source_url":"https://www.jpf.go.jp/e/","source_type":"official_education","publisher":"The Japan Foundation","purpose":"Tổ chức giao lưu văn hóa quốc tế của Nhật Bản; có mảng giáo dục tiếng Nhật ở nước ngoài.","level_scope":"Không áp dụng (trang tổng quan)","license_note":"CHƯA TÌM THẤY điều khoản sử dụng lại trên trang đã đọc. Coi như chưa xác nhận được quyền sử dụng lại → chỉ liên kết, không sao chép.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-22","reuse_allowed":"unknown","notes":"Cần tìm trang chính sách/điều khoản của jpf.go.jp trước khi dùng bất kỳ tài liệu nào của họ.","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-irodori', $ncseed${"version":"","retrieved_at":null,"license_name":"","license_url":"","allowed_use":"Không nhập tự động. Điều khoản chỉ cho phép dùng riêng tư/cơ sở giáo dục, cấm mục đích thương mại; không có dữ liệu mở.","attribution_required":false,"attribution_text":"","import_policy":"blocked","update_history":[],"id":"src-irodori","source_name":"IRODORI — Japanese for Life in Japan","source_url":"https://www.irodori.jpf.go.jp/en/","source_type":"official_education","publisher":"The Japan Foundation Japanese-Language Institute, Urawa","purpose":"Học liệu tiếng Nhật cho cuộc sống ở Nhật (cấp Starter, Elementary 1, Elementary 2, Pre-Intermediate).","level_scope":"Starter – Pre-Intermediate (chưa đối chiếu tương ứng JLPT)","license_note":"Điều khoản (https://www.irodori.jpf.go.jp/en/privacy.html): văn bản/tài liệu chỉ được sao chép, chỉnh sửa cho mục đích riêng tư hoặc cơ sở giáo dục; cấm dùng trang vào mục đích thương mại; không dùng thông tin để tạo học liệu mới không liên quan. Học liệu tự tạo từ trang rồi công khai phải miễn phí và ghi nguồn. → App KHÔNG sao chép nội dung IRODORI; chỉ liên kết để người học tham khảo.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-22","reuse_allowed":"personal_only","notes":"Không đưa nội dung IRODORI vào app thương mại. Nếu muốn dùng trong lớp học/nội bộ, cần đọc kỹ điều khoản và xin phép.","created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
