insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-kanjidic2', $ncseed${"version":"3.6.2+20260406125001 (jmdict-simplified)","retrieved_at":null,"license_name":"CC BY-SA 4.0 + EDRDG Licence","license_url":"https://www.edrdg.org/edrdg/licence.html","allowed_use":"Như JMdict, trừ các trường thuộc mục 8 của giấy phép EDRDG.","attribution_required":true,"attribution_text":"Ứng dụng này dùng tệp KANJIDIC2 của Electronic Dictionary Research and Development Group (EDRDG), sử dụng theo giấy phép của nhóm: https://www.edrdg.org/edrdg/licence.html","import_policy":"allowed","update_history":[],"id":"src-kanjidic2","source_name":"KANJIDIC2 — dữ liệu Kanji (EDRDG)","source_url":"https://www.edrdg.org/wiki/index.php/KANJIDIC_Project","source_type":"dictionary","publisher":"Electronic Dictionary Research and Development Group (EDRDG)","purpose":"Kanji: âm On/Kun, nghĩa tiếng Anh, số nét, lớp học (grade), âm Hán–Việt. Nhập qua gói jmdict-simplified.","level_scope":"Không có cấp JLPT riêng (cấp lấy từ danh sách cộng đồng)","license_note":"CC BY-SA 4.0 kèm điều kiện EDRDG; Mục 8 của giấy phép: một số trường thuộc bản quyền riêng của người đóng góp (mã SKIP — Jack Halpern; pinyin; Four Corner; Morohashi; mô tả Spahn/Hadamitzky; âm Hàn; mã De Roo). Pipeline KHÔNG nhập các trường đó.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-23","reuse_allowed":"conditional","notes":"Chỉ nhập: ký tự, âm On/Kun, nghĩa tiếng Anh, số nét, grade, âm Việt (Hán–Việt). Bản quyền các trường mục 8 không được sao chép.","created_at":"2026-10-23T00:00:00.000Z","updated_at":"2026-10-23T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-23T00:00:00.000Z', '2026-10-23T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-tatoeba', $ncseed${"version":"qua jmdict-examples 3.6.2+20260406125001","retrieved_at":null,"license_name":"CC BY 2.0 FR (một phần CC0)","license_url":"https://creativecommons.org/licenses/by/2.0/fr/","allowed_use":"Dùng lại, chỉnh sửa, kể cả thương mại, với điều kiện nêu tên tác giả/nguồn.","attribution_required":true,"attribution_text":"Câu ví dụ từ dự án Tatoeba (https://tatoeba.org/), CC BY 2.0 FR. Mỗi câu có liên kết tới trang gốc ghi tên người đóng góp.","import_policy":"allowed","update_history":[],"id":"src-tatoeba","source_name":"Tatoeba — kho câu ví dụ cộng đồng","source_url":"https://tatoeba.org/","source_type":"open_dataset","publisher":"Tatoeba và những người đóng góp từng câu","purpose":"Câu ví dụ tiếng Nhật kèm bản dịch tiếng Anh (do biên tập viên JMdict chọn và gắn với nghĩa của từ).","level_scope":"Không có cấp độ (cấp chỉ đặt khi có căn cứ khác)","license_note":"Văn bản câu mặc định CC BY 2.0 FR (trang điều khoản Tatoeba, đọc ngày 2026-10-23): dùng lại phải nêu tên tác giả; một số câu là CC0. Gói dữ liệu giữ ID câu để tra tác giả tại https://tatoeba.org/en/sentences/show/<id>, nhưng KHÔNG chứa tên tác giả → app ghi công bằng liên kết tới từng câu.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-23","reuse_allowed":"conditional","notes":"Chưa có bản dịch tiếng Việt trong gói dữ liệu. Câu do cộng đồng viết nên có thể còn sai; không coi là chính thức.","created_at":"2026-10-23T00:00:00.000Z","updated_at":"2026-10-23T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-23T00:00:00.000Z', '2026-10-23T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lesson_sources (id, data, created_at, updated_at) values ('src-waller-jlpt', $ncseed${"version":"qua gói Japanese Language Data 0.9.0 (dựng 2026-04-14)","retrieved_at":null,"license_name":"CC BY (Waller) / CC BY-SA 4.0 (phân phối lại)","license_url":"http://www.tanos.co.uk/jlpt/sharing/","allowed_use":"Dùng lại kể cả thương mại, có ghi công.","attribution_required":true,"attribution_text":"Phân loại JLPT chuyển thể từ Jonathan Waller's JLPT Resources (http://www.tanos.co.uk/jlpt/), CC BY.","import_policy":"allowed","update_history":[],"id":"src-waller-jlpt","source_name":"Danh sách JLPT cộng đồng của Jonathan Waller (tanos.co.uk) — KHÔNG phải danh sách chính thức","source_url":"http://www.tanos.co.uk/jlpt/","source_type":"open_dataset","publisher":"Jonathan Waller (phân phối lại qua stephenmk/yomitan-jlpt-vocab, davidluzgouveia/kanji-data)","purpose":"Căn cứ để gán cấp N5–N1 cho từ vựng và Kanji nhập vào. Chỉ là ước tính của cộng đồng.","level_scope":"N5–N1","license_note":"CC BY (dữ liệu gốc của Waller), phân phối lại dạng CC BY-SA 4.0 qua gói dữ liệu. Chính JLPT đã ngừng công bố danh sách từ vựng/Kanji chính thức từ 2010 nên đây là danh sách suy ra từ đề cũ; các mục ở ranh giới giữa hai cấp có thể không chính xác.","verification_status":"needs_review","reviewed_by":null,"last_verified":"2026-10-23","reuse_allowed":"conditional","notes":"Ứng dụng luôn ghi 'cấp theo danh sách cộng đồng' cho dữ liệu nhập, không ghi như cấp chính thức.","created_at":"2026-10-23T00:00:00.000Z","updated_at":"2026-10-23T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-23T00:00:00.000Z', '2026-10-23T00:00:00.000Z') on conflict (id) do nothing;
