insert into public.passages (id, data, created_at, updated_at) values ('p-n5-morning', $ncseed${"id":"p-n5-morning","level":"N5","kind":"reading","title":"わたしの朝","body":"{私|わたし}は{毎朝|まいあさ}{七時|しちじ}に{起|お}きます。{朝|あさ}ご{飯|はん}を{食|た}べて、{八時|はちじ}に{家|いえ}を{出|で}ます。{電車|でんしゃ}で{会社|かいしゃ}へ{行|い}きます。","body_vi":"Mỗi sáng tôi dậy lúc 7 giờ. Ăn sáng xong, 8 giờ tôi ra khỏi nhà. Tôi đến công ty bằng tàu điện.","script":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.passages (id, data, created_at, updated_at) values ('p-n5-note', $ncseed${"id":"p-n5-note","level":"N5","kind":"reading","title":"メモ","body":"{田中|たなか}さんへ\n{今日|きょう}は{雨|あめ}です。{傘|かさ}を{持|も}って{来|き}てください。\n{明日|あした}は{休|やす}みです。\n{山田|やまだ}","body_vi":"Gửi anh/chị Tanaka,\nHôm nay trời mưa. Hãy mang ô đến nhé.\nNgày mai được nghỉ.\nYamada","script":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.passages (id, data, created_at, updated_at) values ('p-n5-listen-shop', $ncseed${"id":"p-n5-listen-shop","level":"N5","kind":"listening","title":"みせで","body":"","body_vi":"","script":[{"speaker":"店員","text":"いらっしゃいませ。","vi":"Xin chào quý khách."},{"speaker":"客","text":"すみません、りんごはいくらですか。","vi":"Xin lỗi, táo giá bao nhiêu ạ?"},{"speaker":"店員","text":"{一|ひと}つ{百円|ひゃくえん}です。","vi":"Một quả 100 yên ạ."},{"speaker":"客","text":"じゃあ、{三|みっ}つください。","vi":"Vậy cho tôi 3 quả."}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.passages (id, data, created_at, updated_at) values ('p-n5-listen-plan', $ncseed${"id":"p-n5-listen-plan","level":"N5","kind":"listening","title":"にちようびの よてい","body":"","body_vi":"","script":[{"speaker":"山田","text":"{田中|たなか}さん、{日曜日|にちようび}は{何|なに}をしますか。","vi":"Anh Tanaka, Chủ nhật anh làm gì?"},{"speaker":"田中","text":"{友達|ともだち}と{映画|えいが}を{見|み}に{行|い}きます。","vi":"Tôi đi xem phim với bạn."},{"speaker":"山田","text":"いいですね。{何時|なんじ}からですか。","vi":"Hay quá. Từ mấy giờ vậy?"},{"speaker":"田中","text":"{午後|ごご}{二時|にじ}からです。","vi":"Từ 2 giờ chiều."}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-morning-greeting', $ncseed${"id":"c-morning-greeting","category":"workplace","level_hint":"N5","title":"Chào buổi sáng ở công ty","context":"Chín giờ kém mười lăm sáng. Nguyễn (nhân viên mới) gặp đồng nghiệp Yamada ở văn phòng ナカシマ.","goal":"Chào hỏi lịch sự đầu giờ và xác nhận lịch họp trong ngày.","characters":[{"name":"グエン","role":"Nhân viên mới"},{"name":"山田","role":"Đồng nghiệp (làm lâu hơn)"}],"politeness":"polite","lines":[{"speaker":"山田","ja":"おはようございます。","vi":"Chào buổi sáng."},{"speaker":"グエン","ja":"おはようございます。{今日|きょう}もよろしくお{願|ねが}いします。","vi":"Chào buổi sáng. Hôm nay cũng mong anh/chị giúp đỡ."},{"speaker":"山田","ja":"こちらこそ、よろしくお{願|ねが}いします。{今日|きょう}は{九時|くじ}から{会議|かいぎ}です。","vi":"Tôi cũng vậy, mong được giúp đỡ. Hôm nay có họp từ 9 giờ."},{"speaker":"グエン","ja":"はい、わかりました。{準備|じゅんび}します。","vi":"Vâng, tôi hiểu rồi. Tôi sẽ chuẩn bị."}],"vocab_notes":[{"term":"おはようございます","reading":"おはようございます","meaning_vi":"Chào buổi sáng (lịch sự). Với bạn bè thân có thể nói おはよう."},{"term":"よろしくお願いします","reading":"よろしくおねがいします","meaning_vi":"Cụm xã giao: mong được giúp đỡ/nhờ cậy; dùng khi bắt đầu quan hệ hoặc nhờ việc."},{"term":"会議","reading":"かいぎ","meaning_vi":"cuộc họp"},{"term":"準備","reading":"じゅんび","meaning_vi":"chuẩn bị"}],"grammar_notes":[{"pattern":"〜は〜からです","note_vi":"Chỉ thời điểm bắt đầu: 会議は九時からです (cuộc họp bắt đầu từ 9 giờ)."},{"pattern":"こちらこそ","note_vi":"Đáp lại lời cảm ơn/lời chào: \"tôi mới là người nên nói vậy\"."}],"alternatives":[{"ja":"おはようございます。{今日|きょう}も{一日|いちにち}{頑張|がんば}りましょう。","vi":"Chào buổi sáng. Hôm nay cũng cùng cố gắng nhé.","nuance_vi":"Thân thiện, thường dùng với đồng nghiệp cùng nhóm."},{"ja":"おはよう！","vi":"Chào buổi sáng!","nuance_vi":"Thân mật; thường dành cho bạn bè/đồng nghiệp rất thân, ít dùng với cấp trên."}],"other_situations":[{"situation_vi":"Bắt đầu làm việc cùng một đồng nghiệp mới","ja":"これからどうぞよろしくお{願|ねが}いします。","vi":"Từ nay mong được giúp đỡ."}],"drills":[{"prompt_vi":"Chào đồng nghiệp lúc đầu giờ và nhờ giúp đỡ trong ngày","model_ja":"おはようございます。{今日|きょう}もよろしくお{願|ねが}いします。","hint_vi":"Bắt đầu bằng lời chào buổi sáng lịch sự."},{"prompt_vi":"Nói \"Vâng, tôi sẽ chuẩn bị\" khi được báo có họp","model_ja":"はい、{準備|じゅんび}します。","hint_vi":"Dùng thể ます."}],"roleplay":[{"id":"t1","npc_ja":"おはようございます。","npc_vi":"(Đồng nghiệp chào bạn lúc đầu giờ)","options":[{"ja":"おはようございます。{今日|きょう}もよろしくお{願|ねが}いします。","vi":"Chào buổi sáng. Hôm nay cũng mong anh/chị giúp đỡ.","fit":"best","feedback_vi":"Lịch sự và phù hợp đầu giờ làm.","next":"t2"},{"ja":"おはよう。","vi":"Chào.","fit":"ok","feedback_vi":"Hơi suồng sã nếu chưa thân hoặc người đối diện làm lâu hơn bạn.","next":"t2"},{"ja":"こんばんは。","vi":"Chào buổi tối.","fit":"poor","feedback_vi":"Sai thời điểm: đây là buổi sáng.","next":"t2"}]},{"id":"t2","npc_ja":"{今日|きょう}は{九時|くじ}から{会議|かいぎ}です。","npc_vi":"Hôm nay có họp từ 9 giờ.","options":[{"ja":"はい、わかりました。{準備|じゅんび}します。","vi":"Vâng, tôi hiểu. Tôi sẽ chuẩn bị.","fit":"best","feedback_vi":"Xác nhận đã hiểu và nêu rõ hành động tiếp theo.","next":null},{"ja":"ふうん。","vi":"Ừm.","fit":"poor","feedback_vi":"Quá thờ ơ trong môi trường làm việc.","next":null},{"ja":"{会議|かいぎ}はいやです。","vi":"Tôi không thích họp.","fit":"poor","feedback_vi":"Nói thẳng cảm xúc tiêu cực nghe thiếu chuyên nghiệp.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-report-to-boss', $ncseed${"id":"c-report-to-boss","category":"report-contact","level_hint":"N4","title":"Báo cáo ngắn với trưởng phòng","context":"Nguyễn cần báo cáo kết quả kiểm tra tài liệu cho 課長 (trưởng phòng) khi ông ấy đang ngồi ở bàn làm việc.","goal":"Xin phép ngắt lời lịch sự, báo cáo kết quả ngắn gọn và nêu thời hạn.","characters":[{"name":"グエン","role":"Nhân viên (cấp dưới)"},{"name":"課長","role":"Trưởng phòng (cấp trên)"}],"politeness":"keigo","lines":[{"speaker":"グエン","ja":"{課長|かちょう}、{今|いま}、よろしいでしょうか。","vi":"Trưởng phòng, bây giờ có tiện không ạ?"},{"speaker":"課長","ja":"はい、どうぞ。","vi":"Vâng, mời."},{"speaker":"グエン","ja":"{昨日|きのう}の{件|けん}ですが、{資料|しりょう}の{確認|かくにん}が{終|お}わりました。","vi":"Về việc hôm qua, tôi đã kiểm tra xong tài liệu."},{"speaker":"課長","ja":"ありがとう。{問題|もんだい}はありましたか。","vi":"Cảm ơn. Có vấn đề gì không?"},{"speaker":"グエン","ja":"いいえ、{特|とく}にありません。{明日|あした}までに{提出|ていしゅつ}します。","vi":"Không, không có gì đặc biệt. Tôi sẽ nộp trước ngày mai."},{"speaker":"課長","ja":"わかりました。お{願|ねが}いします。","vi":"Hiểu rồi. Nhờ cậu nhé."}],"vocab_notes":[{"term":"よろしいでしょうか","reading":"よろしいでしょうか","meaning_vi":"Dạng lịch sự của いいですか — \"có được không/có tiện không ạ\"."},{"term":"件","reading":"けん","meaning_vi":"việc/vấn đề (đã được nhắc tới trước đó)"},{"term":"提出","reading":"ていしゅつ","meaning_vi":"nộp (tài liệu, báo cáo)"},{"term":"特に","reading":"とくに","meaning_vi":"đặc biệt; (đi với phủ định) không có gì đặc biệt"}],"grammar_notes":[{"pattern":"〜ですが（前置き）","note_vi":"Dùng が như lời dẫn nhập: 昨日の件ですが… (về việc hôm qua thì…), giúp mở đầu báo cáo nhẹ nhàng."},{"pattern":"〜までに","note_vi":"\"Trước/chậm nhất vào\" một mốc thời gian (hạn chót). Khác với まで (liên tục cho đến)."}],"alternatives":[{"ja":"ご{報告|ほうこく}があります。","vi":"Tôi có việc muốn báo cáo.","nuance_vi":"Rõ mục đích ngay từ đầu; thích hợp khi vấn đề quan trọng."},{"ja":"お{時間|じかん}、よろしいですか。","vi":"Anh/chị có thời gian không ạ?","nuance_vi":"Cách hỏi thời gian rảnh, ngắn gọn."}],"other_situations":[{"situation_vi":"Báo cáo kết quả sau cuộc họp","ja":"{会議|かいぎ}の{結果|けっか}についてご{報告|ほうこく}します。","vi":"Tôi xin báo cáo về kết quả cuộc họp."}],"drills":[{"prompt_vi":"Hỏi cấp trên xem có tiện nói chuyện không","model_ja":"{今|いま}、よろしいでしょうか。","hint_vi":"Dùng よろしい thay cho いい."},{"prompt_vi":"Nói sẽ nộp tài liệu trước ngày mai","model_ja":"{明日|あした}までに{提出|ていしゅつ}します。","hint_vi":"Dùng までに (hạn chót)."}],"roleplay":[{"id":"t1","npc_ja":"はい、どうぞ。","npc_vi":"(Trưởng phòng cho phép bạn nói)","options":[{"ja":"{昨日|きのう}の{件|けん}ですが、{資料|しりょう}の{確認|かくにん}が{終|お}わりました。","vi":"Về việc hôm qua, tôi đã kiểm tra xong tài liệu.","fit":"best","feedback_vi":"Nêu chủ đề rồi báo kết quả: ngắn gọn, rõ ràng.","next":"t2"},{"ja":"あのう、えーと、たぶん{終|お}わりました。","vi":"Ừm… chắc là xong rồi.","fit":"poor","feedback_vi":"Mơ hồ khiến cấp trên không biết trạng thái thực sự; nên nêu rõ kết quả.","next":"t2"}]},{"id":"t2","npc_ja":"ありがとう。{問題|もんだい}はありましたか。","npc_vi":"Cảm ơn. Có vấn đề gì không?","options":[{"ja":"いいえ、{特|とく}にありません。{明日|あした}までに{提出|ていしゅつ}します。","vi":"Không có gì đặc biệt. Tôi sẽ nộp trước ngày mai.","fit":"best","feedback_vi":"Trả lời rõ + nêu thời hạn nộp.","next":null},{"ja":"{大丈夫|だいじょうぶ}です。","vi":"Ổn ạ.","fit":"ok","feedback_vi":"Chấp nhận được, nhưng nên bổ sung bước tiếp theo/thời hạn.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-phone-nakashima', $ncseed${"id":"c-phone-nakashima","category":"phone","level_hint":"N3","title":"Nghe điện thoại từ khách hàng (ナカシマ)","context":"Nguyễn nghe điện thoại tại ナカシマ. Người gọi là Sato của công ty ABC (hư cấu) muốn gặp Yamada, trưởng phòng đang không có ở chỗ.","goal":"Nhận cuộc gọi lịch sự, xử lý khi người cần gặp vắng mặt và hẹn gọi lại.","characters":[{"name":"グエン","role":"Nhân viên ナカシマ (người nghe máy)"},{"name":"佐藤","role":"Khách hàng ở công ty khác"}],"politeness":"keigo","lines":[{"speaker":"グエン","ja":"はい、ナカシマでございます。","vi":"Vâng, ナカシマ xin nghe."},{"speaker":"佐藤","ja":"{株式会社|かぶしきがいしゃ}ABCの{佐藤|さとう}と{申|もう}します。いつもお{世話|せわ}になっております。","vi":"Tôi là Sato của công ty ABC. Xin cảm ơn anh/chị đã luôn giúp đỡ."},{"speaker":"グエン","ja":"こちらこそ、お{世話|せわ}になっております。","vi":"Chúng tôi cũng xin cảm ơn."},{"speaker":"佐藤","ja":"{山田課長|やまだかちょう}はいらっしゃいますか。","vi":"Trưởng phòng Yamada có ở đó không ạ?"},{"speaker":"グエン","ja":"{申|もう}し{訳|わけ}ございません。{山田|やまだ}はただいま{席|せき}を{外|はず}しております。","vi":"Xin lỗi, Yamada hiện đang không có ở chỗ."},{"speaker":"グエン","ja":"{戻|もど}りましたら、{折|お}り{返|かえ}しお{電話|でんわ}いたしましょうか。","vi":"Khi anh ấy quay lại, tôi gọi lại cho anh/chị nhé?"},{"speaker":"佐藤","ja":"はい、お{願|ねが}いします。","vi":"Vâng, nhờ anh/chị."},{"speaker":"グエン","ja":"{佐藤様|さとうさま}ですね。かしこまりました。","vi":"Anh Sato đúng không ạ. Tôi đã rõ."}],"vocab_notes":[{"term":"ございます","reading":"ございます","meaning_vi":"Dạng rất lịch sự của あります/です: ナカシマでございます."},{"term":"と申します","reading":"ともうします","meaning_vi":"Khiêm nhường ngữ của と言います — dùng khi tự giới thiệu."},{"term":"いらっしゃる","reading":"いらっしゃる","meaning_vi":"Tôn kính ngữ của いる/行く/来る (người nghe/người thứ ba được tôn trọng)."},{"term":"席を外す","reading":"せきをはずす","meaning_vi":"rời khỏi chỗ ngồi (tạm vắng)"},{"term":"折り返し","reading":"おりかえし","meaning_vi":"gọi lại/trả lời lại ngay khi có thể"}],"grammar_notes":[{"pattern":"内と外（うち・そと）","note_vi":"Khi nói chuyện với người NGOÀI công ty, thường gọi người trong công ty bằng họ trần (山田) chứ không thêm さん/課長 — đây là quy tắc phổ biến trong giao tiếp công sở, thể hiện sự khiêm nhường về phía mình."},{"pattern":"〜いたします","note_vi":"Khiêm nhường ngữ của します: お電話いたします (tôi xin gọi điện)."},{"pattern":"〜ましょうか","note_vi":"Đề nghị làm gì giúp người khác: 折り返しお電話いたしましょうか."}],"alternatives":[{"ja":"ただいま{電話|でんわ}に{出|で}られません。","vi":"Hiện chưa thể nghe máy.","nuance_vi":"Dùng khi người đó đang bận (họp, tiếp khách)."},{"ja":"{少々|しょうしょう}お{待|ま}ちください。","vi":"Xin đợi một chút ạ.","nuance_vi":"Dùng khi định chuyển máy hoặc kiểm tra thông tin."}],"other_situations":[{"situation_vi":"Khi gọi cho công ty khác và tự giới thiệu","ja":"ナカシマのグエンと{申|もう}します。","vi":"Tôi là Nguyễn của ナカシマ."}],"drills":[{"prompt_vi":"Nhấc máy và xưng tên công ty ナカシマ","model_ja":"はい、ナカシマでございます。","hint_vi":"Dùng ございます."},{"prompt_vi":"Nói trưởng phòng Yamada đang không có ở chỗ (nói với khách)","model_ja":"{山田|やまだ}はただいま{席|せき}を{外|はず}しております。","hint_vi":"Gọi 山田 không kèm chức danh khi nói với người ngoài."}],"roleplay":[{"id":"t1","npc_ja":"{山田課長|やまだかちょう}はいらっしゃいますか。","npc_vi":"Trưởng phòng Yamada có ở đó không ạ? (Yamada đang vắng)","options":[{"ja":"{申|もう}し{訳|わけ}ございません。{山田|やまだ}はただいま{席|せき}を{外|はず}しております。","vi":"Xin lỗi, Yamada hiện đang không có ở chỗ.","fit":"best","feedback_vi":"Xin lỗi + gọi người trong công ty bằng họ trần + lý do vắng ngắn gọn.","next":"t2"},{"ja":"{山田課長|やまだかちょう}はいません。","vi":"Trưởng phòng Yamada không có.","fit":"poor","feedback_vi":"Gắn chức danh cho người nhà với khách và cách nói quá cụt, thiếu lịch sự.","next":"t2"}]},{"id":"t2","npc_ja":"では、また{後|あと}でかけ{直|なお}します。","npc_vi":"Vậy lát nữa tôi sẽ gọi lại.","options":[{"ja":"{恐|おそ}れ{入|い}ります。{戻|もど}りましたら、こちらからお{電話|でんわ}いたしましょうか。","vi":"Xin lỗi vì sự bất tiện. Khi anh ấy quay lại, chúng tôi gọi lại nhé?","fit":"best","feedback_vi":"Chủ động đề nghị gọi lại giúp khách đỡ mất công.","next":null},{"ja":"はい、わかりました。","vi":"Vâng, tôi hiểu rồi.","fit":"ok","feedback_vi":"Không sai nhưng thiếu chủ động và lời xin lỗi.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-request-colleague', $ncseed${"id":"c-request-colleague","category":"request-apology","level_hint":"N4","title":"Nhờ đồng nghiệp kiểm tra giúp tài liệu","context":"Nguyễn vừa viết xong một tài liệu bằng tiếng Nhật và muốn nhờ Yamada (đồng nghiệp lâu năm) kiểm tra giúp.","goal":"Mở đầu lời nhờ một cách nhẹ nhàng, nêu rõ việc nhờ và hạn chót, cảm ơn.","characters":[{"name":"グエン","role":"Người nhờ"},{"name":"山田","role":"Đồng nghiệp"}],"politeness":"polite","lines":[{"speaker":"グエン","ja":"{山田|やまだ}さん、すみません。ちょっとお{願|ねが}いがあるんですが…","vi":"Anh/chị Yamada, xin lỗi. Tôi có chút việc muốn nhờ…"},{"speaker":"山田","ja":"はい、{何|なん}ですか。","vi":"Vâng, việc gì vậy?"},{"speaker":"グエン","ja":"この{資料|しりょう}の{日本語|にほんご}を{確認|かくにん}していただけませんか。","vi":"Anh/chị có thể kiểm tra giúp tiếng Nhật của tài liệu này không ạ?"},{"speaker":"山田","ja":"いいですよ。いつまでですか。","vi":"Được chứ. Đến khi nào?"},{"speaker":"グエン","ja":"{明日|あした}の{午前中|ごぜんちゅう}までにお{願|ねが}いできると{助|たす}かります。","vi":"Nếu nhờ được trước trưa mai thì tôi rất mừng."},{"speaker":"山田","ja":"わかりました。{後|あと}で{見|み}ておきますね。","vi":"Được rồi. Lát nữa tôi xem trước nhé."},{"speaker":"グエン","ja":"ありがとうございます。{助|たす}かります。","vi":"Cảm ơn anh/chị. Giúp tôi nhiều lắm."}],"vocab_notes":[{"term":"ちょっとお願いがあるんですが","reading":"ちょっとおねがいがあるんですが","meaning_vi":"Mở lời nhờ nhẹ nhàng; が ở cuối để câu mở, chờ phản hồi."},{"term":"確認","reading":"かくにん","meaning_vi":"kiểm tra lại, xác nhận"},{"term":"助かります","reading":"たすかります","meaning_vi":"Giúp ích nhiều lắm (cách cảm ơn/đề nghị tự nhiên khi được giúp)."}],"grammar_notes":[{"pattern":"〜ていただけませんか","note_vi":"Cách nhờ lịch sự: \"anh/chị có thể làm giúp tôi … được không ạ?\". Lịch sự hơn 〜てください."},{"pattern":"〜ておく","note_vi":"Làm sẵn/làm trước một việc: 見ておきます (tôi xem trước)."}],"alternatives":[{"ja":"{恐|おそ}れ{入|い}りますが、{確認|かくにん}をお{願|ねが}いできますでしょうか。","vi":"Xin lỗi làm phiền, tôi có thể nhờ anh/chị kiểm tra không ạ?","nuance_vi":"Trang trọng hơn; hợp khi nhờ cấp trên hoặc người ở bộ phận khác."},{"ja":"{確認|かくにん}、お{願|ねが}いしてもいいですか。","vi":"Nhờ anh/chị kiểm tra được không?","nuance_vi":"Thân mật hơn, hợp với đồng nghiệp cùng cấp quen thuộc."}],"other_situations":[{"situation_vi":"Nhờ đồng nghiệp đổi ca","ja":"すみません、{来週|らいしゅう}の{金曜日|きんようび}、シフトを{代|か}わっていただけませんか。","vi":"Xin lỗi, thứ Sáu tuần sau anh/chị có thể đổi ca giúp tôi được không?"}],"drills":[{"prompt_vi":"Mở lời nhờ nhẹ nhàng","model_ja":"すみません、ちょっとお{願|ねが}いがあるんですが…","hint_vi":"Kết thúc bằng んですが…"},{"prompt_vi":"Nhờ đồng nghiệp kiểm tra giúp tài liệu","model_ja":"この{資料|しりょう}を{確認|かくにん}していただけませんか。","hint_vi":"Dùng ていただけませんか."}],"roleplay":[{"id":"t1","npc_ja":"はい、{何|なん}ですか。","npc_vi":"Vâng, việc gì vậy? (sau khi bạn mở lời nhờ)","options":[{"ja":"この{資料|しりょう}の{日本語|にほんご}を{確認|かくにん}していただけませんか。","vi":"Anh/chị có thể kiểm tra giúp tiếng Nhật của tài liệu này không ạ?","fit":"best","feedback_vi":"Cách nhờ lịch sự, nêu rõ việc cần nhờ.","next":"t2"},{"ja":"これ、{確認|かくにん}してください。","vi":"Kiểm tra cái này đi.","fit":"poor","feedback_vi":"Nghe như ra lệnh; không phù hợp khi nhờ đồng nghiệp lâu năm.","next":"t2"}]},{"id":"t2","npc_ja":"いいですよ。いつまでですか。","npc_vi":"Được chứ. Đến khi nào?","options":[{"ja":"{明日|あした}の{午前中|ごぜんちゅう}までにお{願|ねが}いできると{助|たす}かります。","vi":"Nếu nhờ được trước trưa mai thì tôi rất mừng.","fit":"best","feedback_vi":"Nêu hạn chót cụ thể và thể hiện lòng biết ơn.","next":null},{"ja":"できるだけ{早|はや}くお{願|ねが}いします。","vi":"Càng sớm càng tốt nhé.","fit":"ok","feedback_vi":"Không rõ thời hạn nên người nhận khó lên kế hoạch.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-apology-late', $ncseed${"id":"c-apology-late","category":"boss-colleague","level_hint":"N4","title":"Xin lỗi vì đến muộn","context":"Tàu điện bị chậm nên Nguyễn đến công ty muộn mười phút. Trưởng phòng đang ở gần cửa.","goal":"Xin lỗi ngắn gọn, nêu lý do, tiếp nhận lời nhắc nhở và hứa lần sau.","characters":[{"name":"グエン","role":"Nhân viên"},{"name":"課長","role":"Trưởng phòng"}],"politeness":"keigo","lines":[{"speaker":"グエン","ja":"{遅|おく}れて{申|もう}し{訳|わけ}ありません。{電車|でんしゃ}が{遅|おく}れていました。","vi":"Xin lỗi vì đến muộn. Tàu điện bị chậm."},{"speaker":"課長","ja":"{大丈夫|だいじょうぶ}ですよ。{次|つぎ}からは{連絡|れんらく}をお{願|ねが}いしますね。","vi":"Không sao đâu. Từ lần sau nhớ liên lạc nhé."},{"speaker":"グエン","ja":"はい、{気|き}をつけます。","vi":"Vâng, tôi sẽ chú ý."}],"vocab_notes":[{"term":"申し訳ありません","reading":"もうしわけありません","meaning_vi":"Lời xin lỗi trang trọng (trang trọng hơn すみません)."},{"term":"遅れる","reading":"おくれる","meaning_vi":"trễ, muộn"},{"term":"気をつける","reading":"きをつける","meaning_vi":"chú ý, cẩn thận"}],"grammar_notes":[{"pattern":"〜て（原因）","note_vi":"遅れて申し訳ありません: dùng て để nêu nguyên nhân/lý do của lời xin lỗi."},{"pattern":"〜ていました","note_vi":"Trạng thái tiếp diễn trong quá khứ: 電車が遅れていました (tàu đã bị chậm)."}],"alternatives":[{"ja":"{大変|たいへん}{申|もう}し{訳|わけ}ございません。","vi":"Thành thật xin lỗi ạ.","nuance_vi":"Trang trọng hơn; hợp lỗi nghiêm trọng hoặc với khách hàng."},{"ja":"すみません、{遅|おく}れました。","vi":"Xin lỗi, tôi đến muộn.","nuance_vi":"Nhẹ nhàng hơn, hợp với đồng nghiệp thân."}],"other_situations":[{"situation_vi":"Báo trước qua điện thoại khi sẽ đến muộn","ja":"{電車|でんしゃ}が{遅|おく}れているので、{十分|じゅっぷん}ほど{遅|おく}れます。","vi":"Vì tàu bị chậm nên tôi sẽ đến muộn khoảng 10 phút."}],"drills":[{"prompt_vi":"Xin lỗi vì đến muộn vì tàu chậm","model_ja":"{遅|おく}れて{申|もう}し{訳|わけ}ありません。{電車|でんしゃ}が{遅|おく}れていました。","hint_vi":"Xin lỗi trước, nêu lý do sau."},{"prompt_vi":"Hứa sẽ chú ý lần sau","model_ja":"はい、{気|き}をつけます。","hint_vi":"Ngắn gọn, không bào chữa thêm."}],"roleplay":[{"id":"t1","npc_ja":"どうしましたか。","npc_vi":"Có chuyện gì vậy? (khi thấy bạn đến muộn)","options":[{"ja":"{遅|おく}れて{申|もう}し{訳|わけ}ありません。{電車|でんしゃ}が{遅|おく}れていました。","vi":"Xin lỗi vì đến muộn. Tàu bị chậm.","fit":"best","feedback_vi":"Xin lỗi trước, nêu lý do ngắn gọn.","next":null},{"ja":"{電車|でんしゃ}のせいです。","vi":"Tại tàu điện thôi.","fit":"poor","feedback_vi":"Nghe như đổ lỗi, thiếu lời xin lỗi.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-meeting-progress', $ncseed${"id":"c-meeting-progress","category":"meeting","level_hint":"N3","title":"Báo cáo tiến độ trong cuộc họp","context":"Họp tuần của nhóm thiết kế tại ナカシマ. Nguyễn báo cáo tiến độ thiết kế và rủi ro về thời hạn giao linh kiện.","goal":"Báo cáo tiến độ theo tỉ lệ, nêu rủi ro, giải thích nguyên nhân khi được hỏi.","characters":[{"name":"司会","role":"Người điều hành họp"},{"name":"グエン","role":"Kỹ sư thiết kế"},{"name":"課長","role":"Trưởng phòng"}],"politeness":"polite","lines":[{"speaker":"司会","ja":"では、{進捗|しんちょく}を{報告|ほうこく}してください。","vi":"Vậy xin báo cáo tiến độ."},{"speaker":"グエン","ja":"はい。{現在|げんざい}、{設計|せっけい}は{八割|はちわり}ほど{終|お}わっています。ただ、{部品|ぶひん}の{納期|のうき}が{遅|おく}れる{可能性|かのうせい}があります。","vi":"Vâng. Hiện nay thiết kế đã xong khoảng 80%. Tuy nhiên có khả năng thời hạn giao linh kiện sẽ bị chậm."},{"speaker":"課長","ja":"{原因|げんいん}は{何|なん}ですか。","vi":"Nguyên nhân là gì?"},{"speaker":"グエン","ja":"{仕入先|しいれさき}から、{材料|ざいりょう}の{入荷|にゅうか}が{来週|らいしゅう}になると{連絡|れんらく}がありました。","vi":"Nhà cung cấp báo rằng nguyên liệu sẽ về vào tuần sau."},{"speaker":"課長","ja":"わかりました。{代替案|だいたいあん}を{検討|けんとう}してください。","vi":"Hiểu rồi. Hãy xem xét phương án thay thế."}],"vocab_notes":[{"term":"進捗","reading":"しんちょく","meaning_vi":"tiến độ"},{"term":"納期","reading":"のうき","meaning_vi":"thời hạn giao hàng"},{"term":"仕入先","reading":"しいれさき","meaning_vi":"nhà cung cấp (nơi nhập hàng)"},{"term":"代替案","reading":"だいたいあん","meaning_vi":"phương án thay thế"}],"grammar_notes":[{"pattern":"〜割（わり）","note_vi":"割 = phần mười: 八割 = 80%. Dùng nhiều khi báo cáo tiến độ."},{"pattern":"〜可能性がある","note_vi":"Có khả năng (xảy ra): 遅れる可能性があります."},{"pattern":"ただ、〜","note_vi":"Từ nối \"tuy nhiên\" để thêm điều kiện/rủi ro sau thông tin tích cực."}],"alternatives":[{"ja":"{予定|よてい}どおり{進|すす}んでいます。","vi":"Đang tiến hành đúng kế hoạch.","nuance_vi":"Dùng khi không có vấn đề."},{"ja":"{少|すこ}し{遅|おく}れています。","vi":"Đang hơi chậm.","nuance_vi":"Báo sớm về chậm trễ nhẹ."}],"other_situations":[{"situation_vi":"Báo cáo công việc đã hoàn thành","ja":"{図面|ずめん}の{作成|さくせい}は{完了|かんりょう}しました。","vi":"Việc lập bản vẽ đã hoàn thành."}],"drills":[{"prompt_vi":"Báo thiết kế đã xong khoảng 80%","model_ja":"{設計|せっけい}は{八割|はちわり}ほど{終|お}わっています。","hint_vi":"Dùng 〜ほど cho \"khoảng\"."},{"prompt_vi":"Nói có khả năng chậm thời hạn giao hàng","model_ja":"{納期|のうき}が{遅|おく}れる{可能性|かのうせい}があります。","hint_vi":"Dùng 可能性がある."}],"roleplay":[{"id":"t1","npc_ja":"では、{進捗|しんちょく}を{報告|ほうこく}してください。","npc_vi":"Vậy xin báo cáo tiến độ.","options":[{"ja":"はい。{現在|げんざい}、{設計|せっけい}は{八割|はちわり}ほど{終|お}わっています。ただ、{納期|のうき}が{遅|おく}れる{可能性|かのうせい}があります。","vi":"Hiện thiết kế xong khoảng 80%. Tuy nhiên có khả năng chậm thời hạn giao hàng.","fit":"best","feedback_vi":"Nêu tiến độ bằng số + rủi ro — đúng thông tin cần cho cuộc họp.","next":"t2"},{"ja":"{順調|じゅんちょう}です。","vi":"Thuận lợi ạ.","fit":"ok","feedback_vi":"Quá chung chung; nên cho biết số liệu/mốc cụ thể.","next":"t2"}]},{"id":"t2","npc_ja":"{原因|げんいん}は{何|なん}ですか。","npc_vi":"Nguyên nhân là gì?","options":[{"ja":"{仕入先|しいれさき}から、{材料|ざいりょう}の{入荷|にゅうか}が{来週|らいしゅう}になると{連絡|れんらく}がありました。","vi":"Nhà cung cấp báo nguyên liệu sẽ về tuần sau.","fit":"best","feedback_vi":"Nêu nguyên nhân là sự việc cụ thể, không đổ lỗi.","next":null},{"ja":"たぶん、{仕入先|しいれさき}が{悪|わる}いと{思|おも}います。","vi":"Chắc do nhà cung cấp không tốt.","fit":"poor","feedback_vi":"Đoán và đổ lỗi, thiếu căn cứ.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-restaurant-order', $ncseed${"id":"c-restaurant-order","category":"restaurant","level_hint":"N5","title":"Gọi món ở nhà hàng","context":"Hai người vào một quán ramen. Nhân viên đón khách.","goal":"Cho biết số người, gọi món, nhờ thêm nước.","characters":[{"name":"店員","role":"Nhân viên quán"},{"name":"客","role":"Khách"}],"politeness":"polite","lines":[{"speaker":"店員","ja":"いらっしゃいませ。{何名様|なんめいさま}ですか。","vi":"Xin chào quý khách. Quý khách đi mấy người ạ?"},{"speaker":"客","ja":"{二人|ふたり}です。","vi":"Hai người."},{"speaker":"店員","ja":"こちらへどうぞ。ご{注文|ちゅうもん}はお{決|き}まりですか。","vi":"Mời đi lối này. Quý khách đã quyết định gọi món chưa ạ?"},{"speaker":"客","ja":"ラーメンを{二|ふた}つ、お{願|ねが}いします。","vi":"Cho tôi hai bát ramen."},{"speaker":"店員","ja":"かしこまりました。","vi":"Vâng, tôi hiểu rồi ạ."},{"speaker":"客","ja":"すみません、お{水|みず}をください。","vi":"Xin lỗi, cho tôi xin nước."}],"vocab_notes":[{"term":"何名様","reading":"なんめいさま","meaning_vi":"mấy vị (cách hỏi số khách, lịch sự)"},{"term":"ご注文","reading":"ごちゅうもん","meaning_vi":"việc gọi món (kính ngữ của 注文)"},{"term":"かしこまりました","reading":"かしこまりました","meaning_vi":"Tôi đã rõ (dùng của nhân viên với khách)."}],"grammar_notes":[{"pattern":"〜をください","note_vi":"Cho tôi xin ~: お水をください."},{"pattern":"数 + つ","note_vi":"Đếm đồ vật: 一つ (ひとつ)、二つ (ふたつ)、三つ (みっつ)…"}],"alternatives":[{"ja":"{注文|ちゅうもん}をお{願|ねが}いします。","vi":"Cho tôi gọi món.","nuance_vi":"Dùng khi gọi nhân viên để gọi món."},{"ja":"おすすめは{何|なん}ですか。","vi":"Quán có món gợi ý nào không?","nuance_vi":"Hỏi món nên gọi."}],"other_situations":[{"situation_vi":"Thanh toán","ja":"お{会計|かいけい}をお{願|ねが}いします。","vi":"Cho tôi thanh toán."}],"drills":[{"prompt_vi":"Nói bạn đi hai người","model_ja":"{二人|ふたり}です。","hint_vi":"Số người + です."},{"prompt_vi":"Gọi hai bát ramen","model_ja":"ラーメンを{二|ふた}つ、お{願|ねが}いします。","hint_vi":"Dùng bộ đếm つ."}],"roleplay":[{"id":"t1","npc_ja":"{何名様|なんめいさま}ですか。","npc_vi":"Quý khách đi mấy người ạ?","options":[{"ja":"{二人|ふたり}です。","vi":"Hai người.","fit":"best","feedback_vi":"Trả lời đúng và ngắn gọn.","next":"t2"},{"ja":"{二|に}。","vi":"Hai.","fit":"poor","feedback_vi":"Quá cụt và dễ gây hiểu lầm khi thiếu です/人.","next":"t2"}]},{"id":"t2","npc_ja":"ご{注文|ちゅうもん}はお{決|き}まりですか。","npc_vi":"Quý khách đã quyết định gọi món chưa ạ?","options":[{"ja":"ラーメンを{二|ふた}つ、お{願|ねが}いします。","vi":"Cho tôi hai bát ramen.","fit":"best","feedback_vi":"Nêu món và số lượng, lịch sự.","next":null},{"ja":"ラーメン！","vi":"Ramen!","fit":"poor","feedback_vi":"Quá cộc lốc với nhân viên.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-hospital-reception', $ncseed${"id":"c-hospital-reception","category":"hospital","level_hint":"N4","title":"Khám bệnh: nói với lễ tân","context":"Nguyễn đến bệnh viện vì khó chịu từ hôm qua và nói chuyện với lễ tân.","goal":"Nói triệu chứng đơn giản, xuất trình thẻ bảo hiểm và làm theo hướng dẫn chờ gọi tên.","characters":[{"name":"受付","role":"Lễ tân"},{"name":"患者","role":"Bệnh nhân"}],"politeness":"polite","lines":[{"speaker":"受付","ja":"どうされましたか。","vi":"Anh/chị bị làm sao ạ?"},{"speaker":"患者","ja":"{昨日|きのう}から{頭|あたま}が{痛|いた}いです。{熱|ねつ}もあります。","vi":"Từ hôm qua tôi bị đau đầu. Tôi cũng bị sốt."},{"speaker":"受付","ja":"{保険証|ほけんしょう}はお{持|も}ちですか。","vi":"Anh/chị có mang thẻ bảo hiểm không ạ?"},{"speaker":"患者","ja":"はい、これです。","vi":"Có, đây ạ."},{"speaker":"受付","ja":"では、{名前|なまえ}を{呼|よ}びますので、あちらでお{待|ま}ちください。","vi":"Vậy chúng tôi sẽ gọi tên, mời anh/chị chờ ở đằng kia."}],"vocab_notes":[{"term":"どうされましたか","reading":"どうされましたか","meaning_vi":"Anh/chị bị sao ạ? (hỏi lịch sự về tình trạng)."},{"term":"保険証","reading":"ほけんしょう","meaning_vi":"thẻ bảo hiểm"},{"term":"〜が痛い","reading":"〜がいたい","meaning_vi":"bị đau ~ (頭が痛い: đau đầu)"}],"grammar_notes":[{"pattern":"〜から（起点）","note_vi":"昨日から: kể từ hôm qua."},{"pattern":"〜ので〜ください","note_vi":"Vì ~ nên xin hãy ~ (lý do + yêu cầu lịch sự)."}],"alternatives":[{"ja":"{予約|よやく}はしていません。","vi":"Tôi chưa đặt lịch.","nuance_vi":"Trả lời khi lễ tân hỏi về lịch hẹn."}],"other_situations":[{"situation_vi":"Nói bạn đau họng","ja":"{喉|のど}が{痛|いた}いです。","vi":"Tôi bị đau họng."}],"drills":[{"prompt_vi":"Nói từ hôm qua bị đau đầu","model_ja":"{昨日|きのう}から{頭|あたま}が{痛|いた}いです。","hint_vi":"から + が痛い."}],"roleplay":[{"id":"t1","npc_ja":"どうされましたか。","npc_vi":"Anh/chị bị làm sao ạ?","options":[{"ja":"{昨日|きのう}から{頭|あたま}が{痛|いた}いです。","vi":"Từ hôm qua tôi bị đau đầu.","fit":"best","feedback_vi":"Nêu thời điểm bắt đầu và triệu chứng — thông tin cần thiết.","next":null},{"ja":"{調子|ちょうし}が{悪|わる}いです。","vi":"Tôi thấy không khỏe.","fit":"ok","feedback_vi":"Đúng nhưng chung chung; nên nêu triệu chứng cụ thể.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-friends-weekend', $ncseed${"id":"c-friends-weekend","category":"friends","level_hint":"N5","title":"Rủ bạn đi ăn cuối tuần","context":"Minh (bạn người Việt) nói chuyện với Ken (bạn người Nhật) trong giờ nghỉ.","goal":"Rủ bạn đi ăn bằng cách nói thân mật, hỏi ý kiến và hẹn giờ.","characters":[{"name":"ミン","role":"Bạn"},{"name":"ケン","role":"Bạn"}],"politeness":"casual","lines":[{"speaker":"ミン","ja":"{週末|しゅうまつ}、{何|なに}するの？","vi":"Cuối tuần cậu làm gì thế?"},{"speaker":"ケン","ja":"{特|とく}に{予定|よてい}はないよ。","vi":"Không có kế hoạch gì đặc biệt đâu."},{"speaker":"ミン","ja":"じゃあ、{一緒|いっしょ}にご{飯|はん}{食|た}べに{行|い}かない？","vi":"Vậy thì cùng đi ăn cơm không?"},{"speaker":"ケン","ja":"いいね！どこに{行|い}く？","vi":"Hay đấy! Đi đâu?"},{"speaker":"ミン","ja":"ラーメンはどう？","vi":"Ramen thì sao?"},{"speaker":"ケン","ja":"いいよ。{何時|なんじ}にする？","vi":"Được. Mấy giờ nhỉ?"}],"vocab_notes":[{"term":"特に〜ない","reading":"とくに〜ない","meaning_vi":"không có gì đặc biệt"},{"term":"予定","reading":"よてい","meaning_vi":"dự định, lịch"},{"term":"〜はどう？","reading":"〜はどう？","meaning_vi":"~ thì sao? (đề xuất nhẹ)"}],"grammar_notes":[{"pattern":"〜の？（疑問）","note_vi":"Trong văn nói thân mật, の + giọng lên dùng để hỏi, thay cho か: 何するの？"},{"pattern":"〜ない？（誘い）","note_vi":"Rủ rê thân mật: 行かない？ ≈ 行きませんか (dạng lịch sự)."},{"pattern":"〜よ／〜ね","note_vi":"よ: báo thông tin; ね: tìm sự đồng tình. Dùng nhiều trong văn nói thân mật."}],"alternatives":[{"ja":"{一緒|いっしょ}にご{飯|はん}を{食|た}べに{行|い}きませんか。","vi":"Anh/chị đi ăn cùng tôi nhé?","nuance_vi":"Dạng lịch sự, dùng với người không quá thân hoặc cấp trên."}],"other_situations":[{"situation_vi":"Rủ bạn xem phim","ja":"{今度|こんど}の{日曜日|にちようび}、{映画|えいが}{見|み}に{行|い}かない？","vi":"Chủ nhật tới đi xem phim không?"}],"drills":[{"prompt_vi":"Rủ bạn thân đi ăn cơm (thân mật)","model_ja":"{一緒|いっしょ}にご{飯|はん}{食|た}べに{行|い}かない？","hint_vi":"Dùng 〜ない？ khi rủ."},{"prompt_vi":"Hỏi bạn muốn đi đâu (thân mật)","model_ja":"どこに{行|い}く？","hint_vi":"Bỏ ます và lên giọng."}],"roleplay":[{"id":"t1","npc_ja":"{週末|しゅうまつ}、{何|なに}するの？","npc_vi":"Cuối tuần cậu làm gì?","options":[{"ja":"{特|とく}に{予定|よてい}はないよ。{一緒|いっしょ}にご{飯|はん}{食|た}べに{行|い}かない？","vi":"Không có gì đặc biệt. Cùng đi ăn cơm không?","fit":"best","feedback_vi":"Thân mật, tự nhiên và rủ luôn.","next":null},{"ja":"{特|とく}に{予定|よてい}はございません。","vi":"Tôi không có dự định đặc biệt ạ.","fit":"poor","feedback_vi":"Quá trang trọng với bạn thân — nghe xa cách.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-station-directions', $ncseed${"id":"c-station-directions","category":"transport-life","level_hint":"N5","title":"Hỏi đường ra nhà ga","context":"Nguyễn lạc đường gần nhà ga và hỏi một người đi đường.","goal":"Hỏi vị trí, xác nhận hướng đi và khoảng cách.","characters":[{"name":"グエン","role":"Người hỏi đường"},{"name":"通行人","role":"Người đi đường"}],"politeness":"polite","lines":[{"speaker":"グエン","ja":"すみません、{駅|えき}はどこですか。","vi":"Xin lỗi, nhà ga ở đâu ạ?"},{"speaker":"通行人","ja":"あの{信号|しんごう}を{右|みぎ}に{曲|ま}がってください。","vi":"Anh hãy rẽ phải ở đèn tín hiệu kia."},{"speaker":"グエン","ja":"{右|みぎ}ですね。{遠|とお}いですか。","vi":"Rẽ phải ạ. Có xa không?"},{"speaker":"通行人","ja":"いいえ、{歩|ある}いて{五分|ごふん}ぐらいです。","vi":"Không, đi bộ khoảng 5 phút."},{"speaker":"グエン","ja":"ありがとうございます。","vi":"Cảm ơn bạn."}],"vocab_notes":[{"term":"信号","reading":"しんごう","meaning_vi":"đèn tín hiệu giao thông"},{"term":"曲がる","reading":"まがる","meaning_vi":"rẽ, quẹo"},{"term":"〜ぐらい","reading":"〜ぐらい","meaning_vi":"khoảng ~"}],"grammar_notes":[{"pattern":"〜はどこですか","note_vi":"Hỏi vị trí: 駅はどこですか。"},{"pattern":"〜てください","note_vi":"Hướng dẫn/nhờ: 右に曲がってください。"}],"alternatives":[{"ja":"{駅|えき}までどのくらいかかりますか。","vi":"Đến ga mất bao lâu ạ?","nuance_vi":"Hỏi thời gian cần để đi."}],"other_situations":[{"situation_vi":"Hỏi tàu đi Shinjuku","ja":"{新宿|しんじゅく}へ{行|い}く{電車|でんしゃ}は{何番線|なんばんせん}ですか。","vi":"Tàu đi Shinjuku ở đường ray số mấy ạ?"}],"drills":[{"prompt_vi":"Hỏi nhà ga ở đâu","model_ja":"すみません、{駅|えき}はどこですか。","hint_vi":"Mở đầu bằng すみません."}],"roleplay":[{"id":"t1","npc_ja":"あの{信号|しんごう}を{右|みぎ}に{曲|ま}がってください。","npc_vi":"Hãy rẽ phải ở đèn tín hiệu kia.","options":[{"ja":"{右|みぎ}ですね。ありがとうございます。","vi":"Rẽ phải ạ. Cảm ơn bạn.","fit":"best","feedback_vi":"Nhắc lại để xác nhận rồi cảm ơn.","next":null},{"ja":"はい。（{黙|だま}って{行|い}く）","vi":"Vâng. (đi luôn không nói gì)","fit":"poor","feedback_vi":"Nên nói lời cảm ơn khi được chỉ đường.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-email-request', $ncseed${"id":"c-email-request","category":"email","level_hint":"N3","title":"Email nhờ xác nhận tài liệu","context":"Nguyễn gửi email nhờ Yamada (trưởng phòng ở bộ phận khác) xác nhận tài liệu, rồi nhận được thư trả lời.","goal":"Viết email công việc có tiêu đề rõ, lời mở, nội dung nhờ, hạn trả lời và lời kết lịch sự.","characters":[{"name":"グエン","role":"Người gửi"},{"name":"山田","role":"Người nhận"}],"politeness":"keigo","lines":[{"speaker":"グエン（送信）","ja":"{件名|けんめい}：{資料|しりょう}{確認|かくにん}のお{願|ねが}い\n\n{山田様|やまださま}\nお{疲|つか}れ{様|さま}です。ナカシマのグエンです。\n{添付|てんぷ}の{資料|しりょう}をご{確認|かくにん}いただけますでしょうか。\nお{忙|いそが}しいところ{恐|おそ}れ{入|い}りますが、{明日|あした}までにご{返信|へんしん}いただけると{幸|さいわ}いです。\nよろしくお{願|ねが}いいたします。","vi":"Tiêu đề: Nhờ xác nhận tài liệu\n\nAnh Yamada,\nCảm ơn anh đã vất vả. Tôi là Nguyễn của ナカシマ.\nAnh vui lòng xác nhận tài liệu đính kèm giúp tôi được không ạ?\nXin lỗi vì làm phiền khi anh đang bận, nếu anh có thể trả lời trước ngày mai thì tôi rất biết ơn.\nXin nhờ anh giúp đỡ."},{"speaker":"山田（返信）","ja":"グエンさん\nお{疲|つか}れ{様|さま}です。{山田|やまだ}です。\n{資料|しりょう}を{確認|かくにん}しました。{修正|しゅうせい}{点|てん}を{添付|てんぷ}しますので、ご{確認|かくにん}ください。\nよろしくお{願|ねが}いします。","vi":"Nguyễn,\nCảm ơn bạn đã vất vả. Tôi là Yamada.\nTôi đã kiểm tra tài liệu. Tôi đính kèm các điểm cần sửa, bạn xem giúp nhé.\nMong bạn giúp đỡ."}],"vocab_notes":[{"term":"件名","reading":"けんめい","meaning_vi":"tiêu đề (email)"},{"term":"添付","reading":"てんぷ","meaning_vi":"đính kèm"},{"term":"お疲れ様です","reading":"おつかれさまです","meaning_vi":"Cụm chào xã giao phổ biến trong công sở khi đã quen biết nhau; lịch sự hơn có thể dùng いつもお世話になっております."},{"term":"ご返信","reading":"ごへんしん","meaning_vi":"việc trả lời (kính ngữ)"}],"grammar_notes":[{"pattern":"ご〜いただけますでしょうか","note_vi":"Cách nhờ rất lịch sự: ご確認いただけますでしょうか (xin anh/chị vui lòng xác nhận giúp)."},{"pattern":"お忙しいところ恐れ入りますが","note_vi":"Mở đầu khi nhờ vả: \"xin lỗi vì làm phiền khi anh/chị đang bận\"."}],"alternatives":[{"ja":"いつもお{世話|せわ}になっております。","vi":"Cảm ơn anh/chị đã luôn giúp đỡ.","nuance_vi":"Lời chào đầu thư phổ biến, đặc biệt với người ở công ty khác."}],"other_situations":[{"situation_vi":"Kết thư khi cần trả lời","ja":"お{手数|てすう}ですが、ご{返信|へんしん}をお{願|ねが}いいたします。","vi":"Xin lỗi vì làm phiền, mong anh/chị phản hồi."}],"drills":[{"prompt_vi":"Nhờ xác nhận tài liệu đính kèm (rất lịch sự)","model_ja":"{添付|てんぷ}の{資料|しりょう}をご{確認|かくにん}いただけますでしょうか。","hint_vi":"ご + danh từ + いただけますでしょうか."}],"roleplay":[{"id":"t1","npc_ja":"（{山田|やまだ}さんからの{返信|へんしん}）{修正|しゅうせい}{点|てん}を{添付|てんぷ}しますので、ご{確認|かくにん}ください。","npc_vi":"(Thư trả lời của Yamada) Tôi đính kèm điểm cần sửa, bạn xem giúp nhé.","options":[{"ja":"ご{確認|かくにん}ありがとうございます。{修正|しゅうせい}して、{再送|さいそう}いたします。","vi":"Cảm ơn anh đã kiểm tra. Tôi sẽ sửa và gửi lại.","fit":"best","feedback_vi":"Cảm ơn rồi nêu hành động tiếp theo.","next":null},{"ja":"はい。","vi":"Vâng.","fit":"poor","feedback_vi":"Quá cộc lốc trong email công việc.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-keigo-reception', $ncseed${"id":"c-keigo-reception","category":"keigo","level_hint":"N3","title":"Tiếp khách ở quầy lễ tân (kính ngữ)","context":"Nguyễn trực quầy lễ tân tại ナカシマ. Một khách có hẹn với Yamada đến.","goal":"Luyện kính ngữ (尊敬語) khi nói về khách và khiêm nhường ngữ (謙譲語) khi nói về mình/công ty mình.","characters":[{"name":"グエン","role":"Lễ tân"},{"name":"客","role":"Khách"}],"politeness":"keigo","lines":[{"speaker":"グエン","ja":"いらっしゃいませ。ご{用件|ようけん}をお{伺|うかが}いします。","vi":"Xin chào quý khách. Tôi xin hỏi quý khách cần gì ạ."},{"speaker":"客","ja":"{営業部|えいぎょうぶ}の{山田|やまだ}さんと{十時|じゅうじ}にお{約束|やくそく}をいただいております。","vi":"Tôi có hẹn với anh Yamada phòng kinh doanh lúc 10 giờ."},{"speaker":"グエン","ja":"{山田|やまだ}ですね。{確認|かくにん}いたしますので、{少々|しょうしょう}お{待|ま}ちください。","vi":"Yamada phải không ạ. Tôi xin xác nhận, mong quý khách chờ một chút."},{"speaker":"グエン","ja":"お{待|ま}たせいたしました。{山田|やまだ}がすぐ{参|まい}ります。こちらでお{待|ま}ちください。","vi":"Xin lỗi đã để quý khách chờ. Yamada sẽ đến ngay. Mời quý khách chờ ở đây."}],"vocab_notes":[{"term":"伺う","reading":"うかがう","meaning_vi":"Khiêm nhường ngữ của 聞く/訪ねる (hỏi, đến thăm)."},{"term":"参る","reading":"まいる","meaning_vi":"Khiêm nhường ngữ của 行く/来る."},{"term":"少々","reading":"しょうしょう","meaning_vi":"một chút (lịch sự hơn ちょっと)"}],"grammar_notes":[{"pattern":"尊敬語・謙譲語の対応","note_vi":"言う: おっしゃる(尊敬)/申す・申し上げる(謙譲). 行く・来る: いらっしゃる(尊敬)/参る・伺う(謙譲). 見る: ご覧になる(尊敬)/拝見する(謙譲). 食べる: 召し上がる(尊敬)/いただく(謙譲). する: なさる(尊敬)/いたす(謙譲)."},{"pattern":"お〜ください／お〜いたします","note_vi":"Mẫu kính ngữ/khiêm nhường: お待ちください (xin chờ), お待たせいたしました (xin lỗi để quý khách chờ)."}],"alternatives":[{"ja":"どうぞこちらへお{掛|か}けください。","vi":"Mời quý khách ngồi ở đây.","nuance_vi":"Mời khách ngồi chờ."}],"other_situations":[{"situation_vi":"Dẫn khách đến phòng họp","ja":"{会議室|かいぎしつ}までご{案内|あんない}いたします。","vi":"Tôi xin dẫn quý khách đến phòng họp."}],"drills":[{"prompt_vi":"Xin khách chờ một chút (lịch sự)","model_ja":"{少々|しょうしょう}お{待|ま}ちください。","hint_vi":"お + V + ください."},{"prompt_vi":"Xin lỗi vì để khách chờ","model_ja":"お{待|ま}たせいたしました。","hint_vi":"お + V + いたしました."}],"roleplay":[{"id":"t1","npc_ja":"{山田|やまだ}さんと{十時|じゅうじ}にお{約束|やくそく}をいただいております。","npc_vi":"Tôi có hẹn với anh Yamada lúc 10 giờ.","options":[{"ja":"{山田|やまだ}ですね。{確認|かくにん}いたしますので、{少々|しょうしょう}お{待|ま}ちください。","vi":"Yamada phải không ạ. Tôi xin xác nhận, mong quý khách chờ một chút.","fit":"best","feedback_vi":"Dùng 謙譲語 (いたします) cho hành động của mình và お〜ください cho khách.","next":null},{"ja":"{山田|やまだ}さんですね。ちょっと{待|ま}っててください。","vi":"Anh Yamada hả. Chờ chút nhé.","fit":"poor","feedback_vi":"Quá suồng sã với khách; \"山田さん\" cũng không hợp khi nói với khách về người trong công ty.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-casual-contractions', $ncseed${"id":"c-casual-contractions","category":"casual","level_hint":"N4","title":"Nói chuyện thân mật: 〜ちゃった","context":"Hai người bạn thân nói chuyện ở nhà. Một người lỡ ăn hết bánh của người kia.","goal":"Nhận biết cách nói rút gọn thân mật (〜ちゃった) và dùng đúng ngữ cảnh.","characters":[{"name":"A","role":"Bạn thân"},{"name":"B","role":"Bạn thân"}],"politeness":"casual","lines":[{"speaker":"A","ja":"ねえ、これ、{食|た}べちゃった？","vi":"Này, cậu lỡ ăn cái này rồi à?"},{"speaker":"B","ja":"うん、おいしかったから、{全部|ぜんぶ}{食|た}べちゃった。","vi":"Ừ, vì ngon quá nên tớ lỡ ăn hết rồi."},{"speaker":"A","ja":"えー、ひどい！","vi":"Ế, quá đáng!"},{"speaker":"B","ja":"ごめんごめん、{今度|こんど}、{買|か}ってくるよ。","vi":"Xin lỗi xin lỗi, lần sau tớ mua về nhé."}],"vocab_notes":[{"term":"全部","reading":"ぜんぶ","meaning_vi":"tất cả"},{"term":"ひどい","reading":"ひどい","meaning_vi":"tệ, quá đáng (thân mật)"},{"term":"今度","reading":"こんど","meaning_vi":"lần tới / lần này (tùy ngữ cảnh)"}],"grammar_notes":[{"pattern":"〜ちゃった（〜てしまった）","note_vi":"Dạng rút gọn thân mật của 〜てしまった: lỡ làm gì / làm xong hết (nhấn sắc thái tiếc hoặc hoàn tất). Thường gặp trong văn nói; trong văn viết trang trọng dùng 〜てしまった/〜ました."},{"pattern":"ごめんごめん","note_vi":"Lặp đôi để xin lỗi nhẹ nhàng giữa bạn bè; không dùng với cấp trên."}],"alternatives":[{"ja":"{食|た}べてしまいました。","vi":"Tôi đã lỡ ăn mất rồi.","nuance_vi":"Dạng lịch sự, dùng khi nói với người không thân."}],"other_situations":[{"situation_vi":"Lỡ quên điện thoại ở nhà","ja":"{携帯|けいたい}を{忘|わす}れちゃった！","vi":"Tớ lỡ quên điện thoại rồi!"}],"drills":[{"prompt_vi":"Nói với bạn thân là lỡ ăn hết (thân mật)","model_ja":"{全部|ぜんぶ}{食|た}べちゃった。","hint_vi":"〜てしまった → 〜ちゃった."}],"roleplay":[{"id":"t1","npc_ja":"ねえ、これ、{食|た}べちゃった？","npc_vi":"Này, cậu lỡ ăn cái này rồi à?","options":[{"ja":"うん、ごめん。{今度|こんど}{買|か}ってくるよ。","vi":"Ừ, xin lỗi. Lần sau tớ mua về nhé.","fit":"best","feedback_vi":"Thân mật, nhận lỗi và đề nghị bù.","next":null},{"ja":"{大変|たいへん}{申|もう}し{訳|わけ}ございません。","vi":"Thành thật xin lỗi ạ.","fit":"poor","feedback_vi":"Quá trang trọng với bạn thân: nghe lạ/xa cách.","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.conversations (id, data, created_at, updated_at) values ('c-shopping-price', $ncseed${"id":"c-shopping-price","category":"shopping","level_hint":"N5","title":"Hỏi giá và chọn đồ rẻ hơn","context":"Khách hỏi giá một chiếc áo trong cửa hàng và muốn tìm cái rẻ hơn.","goal":"Hỏi giá, hỏi món rẻ hơn, quyết định mua.","characters":[{"name":"客","role":"Khách"},{"name":"店員","role":"Nhân viên"}],"politeness":"polite","lines":[{"speaker":"客","ja":"すみません、これはいくらですか。","vi":"Xin lỗi, cái này giá bao nhiêu ạ?"},{"speaker":"店員","ja":"それは{三千円|さんぜんえん}です。","vi":"Cái đó giá 3.000 yên."},{"speaker":"客","ja":"もう{少|すこ}し{安|やす}いのはありますか。","vi":"Có cái nào rẻ hơn một chút không?"},{"speaker":"店員","ja":"こちらは{二千円|にせんえん}です。","vi":"Cái này giá 2.000 yên."},{"speaker":"客","ja":"じゃあ、それをください。","vi":"Vậy cho tôi cái đó."},{"speaker":"店員","ja":"ありがとうございます。","vi":"Cảm ơn quý khách."}],"vocab_notes":[{"term":"いくら","reading":"いくら","meaning_vi":"bao nhiêu (tiền)"},{"term":"安い","reading":"やすい","meaning_vi":"rẻ"},{"term":"もう少し","reading":"もうすこし","meaning_vi":"thêm một chút nữa"}],"grammar_notes":[{"pattern":"これ・それ・あれ","note_vi":"これ: vật gần người nói; それ: vật gần người nghe; あれ: vật xa cả hai."},{"pattern":"〜のはありますか","note_vi":"Có cái nào ~ không: 安いのはありますか。"}],"alternatives":[{"ja":"{試|ため}してもいいですか。","vi":"Tôi thử được không?","nuance_vi":"Xin thử đồ/sản phẩm."}],"other_situations":[{"situation_vi":"Hỏi có size khác không","ja":"もっと{大|おお}きいサイズはありますか。","vi":"Có size lớn hơn không?"}],"drills":[{"prompt_vi":"Hỏi giá một món đồ","model_ja":"すみません、これはいくらですか。","hint_vi":"いくらですか."},{"prompt_vi":"Hỏi có cái rẻ hơn không","model_ja":"もう{少|すこ}し{安|やす}いのはありますか。","hint_vi":"安いのはありますか."}],"roleplay":[{"id":"t1","npc_ja":"それは{三千円|さんぜんえん}です。","npc_vi":"Cái đó giá 3.000 yên.","options":[{"ja":"もう{少|すこ}し{安|やす}いのはありますか。","vi":"Có cái nào rẻ hơn một chút không?","fit":"best","feedback_vi":"Hỏi lịch sự và không gây khó xử.","next":"t2"},{"ja":"{高|たか}すぎます！","vi":"Đắt quá!","fit":"poor","feedback_vi":"Nghe thiếu lịch sự; nên hỏi có món rẻ hơn không.","next":"t2"}]},{"id":"t2","npc_ja":"こちらは{二千円|にせんえん}です。","npc_vi":"Cái này giá 2.000 yên.","options":[{"ja":"じゃあ、それをください。","vi":"Vậy cho tôi cái đó.","fit":"best","feedback_vi":"Quyết định rõ ràng.","next":null},{"ja":"いりません。","vi":"Không cần.","fit":"poor","feedback_vi":"Cộc lốc; nên nói すみません、また今度…","next":null}]}],"references":[],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-vocab-nature', $ncseed${"id":"l-n5-vocab-nature","level":"N5","module":"vocabulary","title":"Thiên nhiên quanh ta","summary":"9 từ cơ bản về thiên nhiên, có hình minh họa.","order":10,"est_minutes":10,"body":"Bài này gồm các từ chỉ cảnh vật quen thuộc: núi, sông, cây, hoa, bầu trời, mưa, trăng, lửa và nước.\n\nHãy xem hình minh họa, đọc to từ tiếng Nhật rồi đoán nghĩa trước khi lật thẻ. Chú ý **月** vừa là \"trăng\" vừa là \"tháng\", còn **火** (ひ) đồng âm với **日** (ひ) nên phải nhìn chữ Hán để phân biệt.\n\nSau khi học xong, hãy thử trò chơi Picture to Kanji trong Kanji Quest để củng cố.","item_refs":[{"type":"vocabulary","id":"v-yama"},{"type":"vocabulary","id":"v-kawa"},{"type":"vocabulary","id":"v-ki"},{"type":"vocabulary","id":"v-hana"},{"type":"vocabulary","id":"v-sora"},{"type":"vocabulary","id":"v-ame"},{"type":"vocabulary","id":"v-tsuki"},{"type":"vocabulary","id":"v-hi"},{"type":"vocabulary","id":"v-mizu"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-vocab-body', $ncseed${"id":"l-n5-vocab-body","level":"N5","module":"vocabulary","title":"Các bộ phận cơ thể","summary":"Mắt, miệng, tay, tai, chân.","order":20,"est_minutes":8,"body":"Năm từ về cơ thể thường gặp khi đi khám bệnh hoặc mô tả triệu chứng.\n\nMẹo ghi nhớ: các chữ **目**, **口**, **手**, **耳**, **足** đều bắt nguồn từ hình dạng của bộ phận đó, nên rất hợp với phương pháp học bằng hình ảnh.","item_refs":[{"type":"vocabulary","id":"v-me"},{"type":"vocabulary","id":"v-kuchi"},{"type":"vocabulary","id":"v-te"},{"type":"vocabulary","id":"v-mimi"},{"type":"vocabulary","id":"v-ashi"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-vocab-food', $ncseed${"id":"l-n5-vocab-food","level":"N5","module":"vocabulary","title":"Đồ ăn và thức uống","summary":"Táo, trà, bánh mì, trứng, cơm, sữa, thịt, cá.","order":30,"est_minutes":10,"body":"Các từ về đồ ăn thức uống dùng hằng ngày. Lưu ý **ご飯** vừa là \"cơm\" vừa chỉ \"bữa ăn\" (朝ご飯 = bữa sáng).\n\nHãy đặt câu với mẫu **〜を食べます／飲みます** để luyện trợ từ を.","item_refs":[{"type":"vocabulary","id":"v-ringo"},{"type":"vocabulary","id":"v-ocha"},{"type":"vocabulary","id":"v-pan"},{"type":"vocabulary","id":"v-tamago"},{"type":"vocabulary","id":"v-gohan"},{"type":"vocabulary","id":"v-gyunyu"},{"type":"vocabulary","id":"v-niku"},{"type":"vocabulary","id":"v-sakana"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-vocab-things', $ncseed${"id":"l-n5-vocab-things","level":"N5","module":"vocabulary","title":"Đồ vật và nơi chốn quanh ta","summary":"Sách, xe, tàu điện, nhà, trường, đồng hồ, ô, giày, cửa sổ, bàn, ghế, điện thoại, ga.","order":40,"est_minutes":12,"body":"Từ vựng về đồ vật trong nhà và nơi chốn. Nhiều từ này xuất hiện trong mẫu **〜があります／います** (có ... ở đâu).\n\nThử miêu tả căn phòng của bạn bằng 3 câu đơn giản.","item_refs":[{"type":"vocabulary","id":"v-hon"},{"type":"vocabulary","id":"v-kuruma"},{"type":"vocabulary","id":"v-densha"},{"type":"vocabulary","id":"v-ie"},{"type":"vocabulary","id":"v-gakkou"},{"type":"vocabulary","id":"v-tokei"},{"type":"vocabulary","id":"v-kasa"},{"type":"vocabulary","id":"v-kutsu"},{"type":"vocabulary","id":"v-mado"},{"type":"vocabulary","id":"v-tsukue"},{"type":"vocabulary","id":"v-isu"},{"type":"vocabulary","id":"v-denwa"},{"type":"vocabulary","id":"v-eki"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-kanji-days', $ncseed${"id":"l-n5-kanji-days","level":"N5","module":"kanji","title":"Chữ Hán của các thứ trong tuần","summary":"日・月・火・水・木・金・土.","order":50,"est_minutes":12,"body":"Bảy chữ Hán này tạo nên tên các thứ trong tuần: 日曜日 (Chủ nhật), 月曜日 (thứ Hai), 火曜日, 水曜日, 木曜日, 金曜日, 土曜日.\n\nChú ý: mỗi chữ có cách đọc on'yomi dùng trong tên thứ (ニチ, ゲツ, カ, スイ, モク, キン, ド) và cách đọc kun'yomi khi đứng riêng (ひ, つき, ひ, みず, き, かね, つち).","item_refs":[{"type":"kanji","id":"k-nichi"},{"type":"kanji","id":"k-getsu"},{"type":"kanji","id":"k-ka"},{"type":"kanji","id":"k-sui"},{"type":"kanji","id":"k-moku"},{"type":"kanji","id":"k-kin"},{"type":"kanji","id":"k-do"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-kanji-nature', $ncseed${"id":"l-n5-kanji-nature","level":"N5","module":"kanji","title":"Chữ Hán cơ bản: núi, sông, ruộng, người, to, nhỏ, giữa","summary":"山・川・田・人・大・小・中.","order":60,"est_minutes":12,"body":"Những chữ Hán đơn giản có hình dáng gợi nhớ. Hãy tập viết theo thứ tự nét và đọc cả cách đọc on'yomi lẫn kun'yomi.\n\nKhi gặp từ ghép (ví dụ 大学, 小学校), hãy học theo TỪ thay vì chỉ học từng chữ — vì cách đọc có thể thay đổi.","item_refs":[{"type":"kanji","id":"k-san"},{"type":"kanji","id":"k-sen"},{"type":"kanji","id":"k-ta"},{"type":"kanji","id":"k-jin"},{"type":"kanji","id":"k-dai"},{"type":"kanji","id":"k-shou"},{"type":"kanji","id":"k-chuu"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-grammar-basic', $ncseed${"id":"l-n5-grammar-basic","level":"N5","module":"grammar","title":"Câu cơ bản: は・を・に・があります","summary":"Bốn mẫu câu nền tảng.","order":70,"est_minutes":20,"body":"Bốn mẫu câu này là xương sống của tiếng Nhật sơ cấp: giới thiệu bản thân với **〜は〜です**, nói tân ngữ với **を**, nói đích đến/thời điểm với **に**, và nói sự tồn tại với **があります／います**.\n\nHãy đọc từng điểm ngữ pháp, rồi làm bài luyện tập ngữ pháp ở trang JLPT N5.","item_refs":[{"type":"grammar","id":"g-wa-desu"},{"type":"grammar","id":"g-o-particle"},{"type":"grammar","id":"g-ni-particle"},{"type":"grammar","id":"g-ga-arimasu"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-grammar-request', $ncseed${"id":"l-n5-grammar-request","level":"N5","module":"grammar","title":"Mong muốn, rủ rê và nhờ vả","summary":"〜たいです・〜ませんか・〜てください.","order":80,"est_minutes":20,"body":"Ba mẫu câu rất hữu ích trong giao tiếp: nói điều mình muốn (**〜たいです**), mời ai làm gì (**〜ませんか**) và nhờ vả (**〜てください**).\n\nSau bài này hãy sang phần Giao tiếp để xem các mẫu này được dùng trong tình huống thật.","item_refs":[{"type":"grammar","id":"g-tai-desu"},{"type":"grammar","id":"g-masen-ka"},{"type":"grammar","id":"g-te-kudasai"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-conv-greeting', $ncseed${"id":"l-n5-conv-greeting","level":"N5","module":"conversation","title":"Chào hỏi ở công ty","summary":"Hội thoại đầu giờ làm với đồng nghiệp.","order":90,"est_minutes":10,"body":"Học cách chào buổi sáng lịch sự và xác nhận việc được giao. Sau khi đọc hội thoại, hãy thử phần \"Chọn câu đáp\" để xem phản hồi cho từng cách nói.","item_refs":[{"type":"conversation","id":"c-morning-greeting"},{"type":"conversation","id":"c-restaurant-order"},{"type":"conversation","id":"c-shopping-price"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n5-reading-1', $ncseed${"id":"l-n5-reading-1","level":"N5","module":"reading","title":"Đọc hiểu ngắn: buổi sáng và ghi chú","summary":"Hai đoạn đọc ngắn kèm câu hỏi.","order":100,"est_minutes":10,"body":"Đọc kỹ từng đoạn rồi trả lời câu hỏi. Mẹo: gạch chân giờ giấc và địa điểm trước khi nhìn các phương án.","item_refs":[{"type":"passage","id":"p-n5-morning"},{"type":"passage","id":"p-n5-note"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
