insert into public.lessons (id, data, created_at, updated_at) values ('l-n4-grammar-1', $ncseed${"id":"l-n4-grammar-1","level":"N4","module":"grammar","title":"Ngữ pháp N4 (gợi ý): ながら・たことがある・ので","summary":"Ba mẫu câu thường gặp.","order":20,"est_minutes":15,"body":"Ba mẫu câu mở rộng khả năng diễn đạt: hành động đồng thời, kinh nghiệm đã từng và nêu lý do lịch sự.","item_refs":[{"type":"grammar","id":"g-nagara"},{"type":"grammar","id":"g-koto-ga-aru"},{"type":"grammar","id":"g-node"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n4-conv-workplace', $ncseed${"id":"l-n4-conv-workplace","level":"N4","module":"conversation","title":"Giao tiếp công sở: báo cáo, nhờ vả, xin lỗi","summary":"Ba tình huống công sở thường gặp.","order":30,"est_minutes":15,"body":"Ba hội thoại ngắn về báo cáo với cấp trên, nhờ đồng nghiệp và xin lỗi khi đến muộn. Chú ý sự khác nhau về mức lịch sự giữa các vai.","item_refs":[{"type":"conversation","id":"c-report-to-boss"},{"type":"conversation","id":"c-request-colleague"},{"type":"conversation","id":"c-apology-late"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n3-vocab-abstract', $ncseed${"id":"l-n3-vocab-abstract","level":"N3","module":"vocabulary","title":"Từ trừu tượng và từ công việc (N3 gợi ý)","summary":"経験, 責任, 約束, 相談, 確認, 報告, 参加.","order":10,"est_minutes":12,"body":"Các từ này trừu tượng nên không có hình minh họa đơn lẻ — hãy học qua tình huống và câu ví dụ.","item_refs":[{"type":"vocabulary","id":"v-keiken"},{"type":"vocabulary","id":"v-sekinin"},{"type":"vocabulary","id":"v-yakusoku"},{"type":"vocabulary","id":"v-soudan"},{"type":"vocabulary","id":"v-kakunin"},{"type":"vocabulary","id":"v-houkoku"},{"type":"vocabulary","id":"v-sanka"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n3-conv-phone-meeting', $ncseed${"id":"l-n3-conv-phone-meeting","level":"N3","module":"conversation","title":"Điện thoại và họp tiến độ","summary":"Nghe điện thoại ナカシマ, báo cáo tiến độ.","order":20,"est_minutes":20,"body":"Hai tình huống công việc nâng cao: nghe điện thoại bằng kính ngữ và báo cáo tiến độ trong cuộc họp. Hãy luyện phần phản xạ bằng cách nói to.","item_refs":[{"type":"conversation","id":"c-phone-nakashima"},{"type":"conversation","id":"c-meeting-progress"},{"type":"conversation","id":"c-email-request"},{"type":"conversation","id":"c-keigo-reception"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
insert into public.lessons (id, data, created_at, updated_at) values ('l-n2-work', $ncseed${"id":"l-n2-work","level":"N2","module":"vocabulary","title":"Từ vựng & ngữ pháp N2 (gợi ý) cho công việc","summary":"検討・納期・対応・影響 và わけにはいかない.","order":10,"est_minutes":12,"body":"Các từ xuất hiện nhiều trong môi trường sản xuất. Lưu ý chữ **納** có nhiều cách đọc — học theo từ.","item_refs":[{"type":"vocabulary","id":"v-kentou"},{"type":"vocabulary","id":"v-nouki"},{"type":"vocabulary","id":"v-taiou"},{"type":"vocabulary","id":"v-eikyou"},{"type":"grammar","id":"g-wake-ni-wa-ikanai"},{"type":"kanji","id":"k-nou"}],"tags":[],"origin":"ai_generated","status":"ai_generated","hidden":false,"source_id":"src-ai-seed","source_note":"AI (Claude) soạn ngày 2026-10-22 cho dữ liệu mẫu; chưa có giáo viên/người bản ngữ rà soát.","reviewed_by":null,"last_verified":null,"created_at":"2026-10-22T00:00:00.000Z","updated_at":"2026-10-22T00:00:00.000Z"}$ncseed$::jsonb, '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z') on conflict (id) do nothing;
